WORKS = [
dict(COMUM, work='W-000142', codigo='B2B-13',
 titulo='Refidelização pura e simples B2B: renovação de prazo sem alteração de escopo (aditivo de tempo)',
 nota='US de negócio B2B (documento de 10/09, "Histórias novas", história 26; decisões de 10/09 na W-000100 notas (c) e (f); comentários de negócio de 14/09 na história 14: refidelização cobre todas as etiquetas do contrato guarda-chuva e prazo "e outros").',
 como='Gerente de Relacionamento',
 quero='renovar o prazo de fidelidade de um contrato B2B ativo, sem alterar produtos, quantidades nem valores, escolhendo 12, 24, 36, 48, 60 meses ou prazo customizado, com aditivo de tempo gerado pelo sistema e aprovação do BKO',
 para_que='a vigência jurídica seja estendida e o MRR garantido sem abrir ordem de alteração técnica.',
 contexto=['A W-000100 trata refidelização só junto com upgrade. Não existe fluxo de renovação de prazo sem mexer no escopo, que é a operação mais frequente de retenção preventiva. O contrato B2B é guarda-chuva: a renovação vale para todas as etiquetas e ativos do contrato. Sem Arquitetura, sem carrinho e sem Order Management: só datas, aditivo, aprovação e sincronização de vigência com o Customer Core.'],
 regras=[
  'RN-01 Entrada pela Visão 360º do grupo econômico (B2B-10) no contrato escolhido. Perfis: GR dono da conta e gestor; SDR não executa.',
  'RN-02 Elegibilidade: Contract com Status na categoria Activated e sem outra Opportunity aberta de record type Alteração Contratual ou Refidelização Simples para o mesmo contrato; havendo, o sistema bloqueia e aponta a oportunidade em andamento.',
  'RN-03 Prazo: picklist 12, 24, 36, 48, 60 meses ou "Outro" (número de meses) com justificativa obrigatória, como já decidido na W-000100 (c).',
  'RN-04 Escopo travado: o OmniScript exibe os ativos do contrato em somente leitura (nome, atributos principais, MRC atual). Sem carrinho, sem adicionar ou remover item, sem alterar preço. Necessidade de mudança de escopo encerra este fluxo e direciona ao MACD (W-000100 ou W-000125).',
  'RN-05 Vigência: grava novo Contract Term (months) e Contract Start Date da vigência renovada; Contract End Date é calculada pela configuração padrão do Contract (start + term). A Data Fim de Fidelidade (campo custom no Contract e nos Assets do contrato) é atualizada em todas as etiquetas do contrato.',
  'RN-06 Aditivo de tempo pelo Amend Frame Agreement do Industries CLM (TEC-CLM-01) com contract type próprio "Aditivo de Refidelização": nasce ligado ao contrato master (lista Amendment Contracts); no aditivo o sistema grava Contract Start Date e Contract Term e estende a Effective End Date dos descontos contract-based do frame agreement (desconto de fidelidade B2B, W-000100 nota g). Como o Amend não copia os termos gerais, o template do aditivo carrega as cláusulas de renovação. Aceite pelo signatário legal conforme B2B-09.',
  'RN-07 Ciclo do aditivo pelo Contract State Model do CLM: Rascunho > Aguardando Aceite > Aguardando BKO > Ativo (ou Rejeitado), com Vlocity Actions por estado e Applicable User Profile: o GR só cria e envia; a ação "Aprovar Aditivo" aparece apenas para o perfil BKO no estado Aguardando BKO. O BKO só lê, não edita valores (W-000101).',
  'RN-08 Sincronização: na transição para Ativo, Integration Procedure envia as novas datas de vigência ao Customer Core pelo endpoint proprietário via MuleSoft (decisão 04/09, W-000087); TMF651 fica como mapa de capacidade. Só com retorno 200 o contrato passa a "Renovado" e a oportunidade a Ganha.',
  'RN-09 Nenhuma ordem técnica, nenhuma tarefa de Arquitetura, nenhuma submissão ao OM.',
  'RN-10 Alerta pré-vencimento: scheduled path no Contract com Time Source = Data Fim de Fidelidade e offset de 60 dias antes (parametrizável em Custom Metadata) cria Task para o GR; o path é cancelado automaticamente se o contrato deixar de atender (renovado, cancelado) e reagendado se a data mudar.',
  'RN-11 Desconto de fidelidade: no B2B ele é contract-based discount do frame agreement e a RN-06 estende sua vigência sem tocar nos assets. Se algum ativo tiver ajuste de promoção com Time Plan/Time Policy (Source = ABP), a nova duração é aplicada pelo Repricing Batch Processor restrito aos assets da conta, em lotes de até 20 line items, porque o repricing atualiza as datas de efetividade dos ajustes de promoção. Fora desse caso, nenhum repricing de assets: manter "Retain Original Price during MACD".',
  'RN-12 Sem multa (não há alteração de escopo nem cancelamento). Reajuste financeiro não tramita aqui (W-000100 nota b).'],
 especificacao=['Opportunity record type "Refidelização Simples" criada a partir da 360 (B2B-10); OmniScript "Renovação Contratual B2B" com FlexCard de ativos em somente leitura (Integration Procedure lendo Assets por Contract e Asset Reference ID); campos custom no Contract: Data Fim de Fidelidade, Prazo de Fidelidade (meses), Justificativa de Prazo; Validation Rule para RN-02; Vlocity CLM Amend com contract type "Aditivo de Refidelização" e template próprio (TEC-CLM-01, W-000106); Contract State Model e Vlocity Actions por perfil; Integration Procedure de sincronização via Named Credential MuleCallout / IntegrationConfig__mdt; record-triggered flow no Contract com scheduled path (RN-10); Custom Metadata para offset do alerta e lista de prazos.'],
 dependencias='W-000123 (B2B-10, ponto de entrada), W-000100 (regras de prazo e justificativa), W-000126 (TEC-CLM-01 aditivo), W-000122 (B2B-09 signatário), W-000101 (fila BKO), W-000087 (integrações), W-000103 (Assets com fidelidade carregada), P1 do Joel (prazo de contrato na oferta).',
 riscos='Customer Core precisa devolver as vigências atuais e aceitar update de datas; contratos sem Asset sincronizado não podem ser renovados pela 360; CLM precisa estar ativo na org (verificação de 15/09).',
 estimativa='8 Story Points.',
 criterios=[
  ('Elegibilidade e trava', 'um contrato B2B ativo com uma Opportunity de Alteração Contratual aberta', 'o GR aciona "Refidelizar" na 360', 'o sistema bloqueia e exibe o número da oportunidade em andamento.'),
  ('Prazo padrão', 'um contrato ativo há 12 meses sem MACD aberto', 'o GR escolhe 24 meses e confirma', 'o sistema gera o aditivo sem acionar Arquitetura e envia à fila de aprovação do BKO.'),
  ('Prazo customizado', 'o OmniScript de renovação', 'o GR escolhe "Outro" e informa 18 meses sem justificativa', 'o sistema bloqueia o avanço até a justificativa ser preenchida.'),
  ('Escopo somente leitura', 'o OmniScript carregado', 'o GR visualiza os ativos', 'eles aparecem em somente leitura e não existe ação de adicionar item, remover item ou alterar preço.'),
  ('Aditivo e datas', 'o aditivo de 36 meses aceito pelo signatário legal e aprovado pelo BKO', 'a sincronização com o Customer Core retorna sucesso', 'Contract Term = 36, Contract End Date recalculada, Data Fim de Fidelidade atualizada em todos os assets do contrato e o aditivo listado em Amendment Contracts.'),
  ('BKO obrigatório', 'o aditivo em Aguardando BKO', 'um usuário GR abre o registro', 'a ação "Aprovar Aditivo" não aparece; e enquanto o BKO não aprova, nenhuma chamada ao Customer Core é feita e o contrato permanece com os dados anteriores.'),
  ('Alerta pré-vencimento', 'um contrato com Data Fim de Fidelidade em 60 dias', 'o scheduled path executa', 'uma Task é criada para o GR; e se o contrato for renovado antes, o path pendente é cancelado sem gerar Task.'),
  ('Guarda-chuva', 'um contrato com três etiquetas ativas', 'a refidelização é concluída', 'as três recebem a mesma Data Fim de Fidelidade.'),
  ('Desconto de fidelidade', 'um frame agreement com desconto contract-based vencendo em 31/12', 'a refidelização de 24 meses é ativada', 'a Effective End Date do desconto passa para 24 meses após o novo início e os MRC dos assets não mudam.')],
 massa='Business Account (CNPJ) com contrato de conectividade ativo há 12 meses e três assets; renovação para 36 meses; usuário perfil BKO para aprovar; contrato com oportunidade de upgrade aberta para o critério 1.',
 fundamentacao=['Salesforce Help: Contract Lifecycle Management Overview; To Amend Frame Agreements; Contract State Model and the Contract Workflow; Contract Fields; Scheduled Paths (record-triggered flow); Reprice Existing Prices; Set Up Attribute-Based Pricing with Time Plan and Time Policy; Vlocity CLM Custom Settings.']),

dict(COMUM, work='W-000143', codigo='B2B-14',
 titulo='Aviso prévio de cancelamento B2B: prazo de 30/60/90 dias, janela de reversão, painel e corte automático',
 nota='US de negócio B2B (documento de 10/09, "Histórias novas", história 27; continuação da W-000099; comentários de negócio de 14/09 nas histórias 4 e 13: entradas pela Célula de Retenção, Central de Cancelamento e GR restrito à carteira; Arquitetura não atua na retenção). Atenção: o case Salesforce 473919801 (jun-jul/2026) e os entitlements de produção (15/09) mostram que a licença de Industries OM em produção venceu em 16/06/2026; confirmar a provisão antes de planejar esta US para produção.',
 como='Central de Cancelamentos / Analista de Retenção BKO B2B',
 quero='registrar o prazo de aviso prévio do cancelamento corporativo, acompanhar a janela num painel e ter a desativação técnica e o Billing Stop disparados automaticamente só ao fim do prazo',
 para_que='o serviço continue operante e faturado durante o aviso, a retenção tenha uma janela de reversão e o corte não dependa de planilha.',
 contexto=['A W-000099 cobre a solicitação, as esteiras de retenção e o cálculo da multa e, na efetivação, dispara o Billing Stop. No B2B existe aviso prévio contratual de 30, 60 ou 90 dias entre a efetivação e o corte, hoje controlado em planilha. Esta US insere a janela entre a efetivação da W-000099 e o corte, com reversão possível e execução automática no D-Day.'],
 regras=[
  'RN-01 Ao efetivar o cancelamento (fim das esteiras da W-000099) o usuário informa o Aviso Prévio: 30, 60 ou 90 dias (valores em Custom Metadata). Data Fim do Aviso Prévio = data de efetivação + prazo, gravada na Opportunity de cancelamento e no Contract.',
  'RN-02 Status durante a janela: Contract Status "Em Aviso Prévio" (valor custom na categoria Activated, para o contrato seguir ativo em relatórios); Opportunity de cancelamento em "Aguardando Fim do Aviso Prévio".',
  'RN-03 Durante a janela nada é submetido ao Order Management nem ao Customer Core. Motivo: uma ordem de desativação submetida só pode ser cancelada in-flight antes do Point of No Return e gera ordem suplementar com rollback. A ordem de desativação só é criada no D-Day.',
  'RN-04 Agendamento do corte: record-triggered flow no Contract com scheduled path, Time Source = Data Fim do Aviso Prévio, offset 1 dia depois, condição Status = "Em Aviso Prévio", batch 200. No disparo, Integration Procedure converte os assets do contrato em ordem (Convert Asset to Order, Assets Action Type Change, ação Delete no root bundle; quantidades desabilitadas e one-time charges não carregadas, comportamento padrão da conversão), submete ao OM (TEC-OM-01) e a decomposição gera a ordem técnica de desativação ao Customer Core pelo endpoint proprietário (TMF622 como mapa). O Billing Stop segue a regra da W-000099: só após callback do Customer Core.',
  'RN-05 Reversão: ação "Reverter Cancelamento" visível para Retenção/BKO, Central de Cancelamentos e GR dono da conta. Exige motivo de retenção (lista da W-000096) e oferta de retenção aceita quando houver (CAT-RET-01, gera pedido de alteração via W-000100); Contract Status volta a Activated e a Opportunity fecha como "Retido". Com a mudança de status o registro deixa de atender à condição do path e o agendamento é cancelado automaticamente, sem passo manual.',
  'RN-06 Renegociação do prazo (ex.: de 90 para 60 dias): alterar a Data Fim do Aviso Prévio reagenda o corte para a nova data, desde que futura; data no passado é bloqueada por Validation Rule.',
  'RN-07 Painel: Lightning Dashboard e list views de contratos "Em Aviso Prévio" com dias restantes (campo fórmula), GR, célula de retenção e MRR em risco. GR enxerga só a própria carteira (sharing por Account Owner e equipe); Retenção e Central veem tudo.',
  'RN-08 Após o corte: Assets com provisioning status Deleted e status "Cancelado", Contract Status "Encerrado", Opportunity de cancelamento Ganha (churn efetivado), conforme W-000099.',
  'RN-09 Falha na execução: a plataforma retenta o scheduled path em 15, 30, 60, 120 e 240 minutos; persistindo, o flow cria Task para o BKO e o registro fica em "Corte com Falha" no painel. Fallout de orquestração é tratado no OM (Fallout Handling).',
  'RN-10 Reversão após o D-Day (ordem já submetida): só o BKO pode cancelar a ordem in-flight, e apenas antes do Point of No Return; depois disso a reativação é uma venda nova (W-000097 em diante).',
  'RN-11 Limites: 250.000 scheduled paths por 24 h; callouts em massa saem do OM/MuleSoft e não do flow; Default Workflow User configurado.'],
 especificacao=['Campos no Contract: Prazo de Aviso Prévio (picklist), Data Fim do Aviso Prévio (Date), Dias Restantes (fórmula), Motivo de Retenção (lookup à lista global); valores de Status "Em Aviso Prévio" e "Encerrado"; record-triggered flow "Contrato - Corte por Aviso Prévio" com scheduled path chamando Integration Procedure que usa a implementação ABO (Convert Asset to Order, ação Delete) e o checkout do TEC-OM-01; Quick Action "Reverter Cancelamento" (screen flow) com Permission Set; Validation Rule para data passada; Custom Metadata dos prazos; Dashboard e list views com sharing por carteira; acompanhamento em Setup > Time-Based Automations e logs FLOW_SCHEDULED_PATH_QUEUED.'],
 dependencias='W-000099 (efetivação, multa, Billing Stop), W-000118 (TEC-OM-01 submissão), W-000088 (decomposição), W-000087 (integrações), W-000128 (CAT-RET-01 ofertas de retenção), W-000096 (motivos), W-000123 (360), W-000103 (Assets sincronizados), W-000090 (perfis e permissões), licença de Industries OM em produção (W-000134).',
 riscos='Customer Core sem execução programada exige que o Salesforce dispare no dia exato (assumido nesta US); contratos sem Asset não podem gerar ordem ABO; lista de entradas e alçadas com a Tayza (comentário de 14/09).',
 estimativa='8 Story Points.',
 criterios=[
  ('Prazo e data', 'um cancelamento efetivado em 01/10 com aviso prévio de 30 dias', 'o usuário confirma', 'Data Fim do Aviso Prévio = 31/10, Contract Status = "Em Aviso Prévio" e o contrato aparece no painel com 30 dias restantes.'),
  ('Nada no OM durante a janela', 'um contrato em aviso prévio', 'se consulta as ordens do contrato durante a janela', 'não existe ordem de desativação criada nem submetida ao OM e o faturamento segue ativo.'),
  ('Corte automático', 'um contrato com Data Fim do Aviso Prévio em 31/10 e sem reversão', 'o sistema atinge 01/11 (data manipulada em QA)', 'o scheduled path cria e submete a ordem ABO de desconexão, o Customer Core recebe a ordem técnica e, após o callback, o Billing Stop é enviado e os assets ficam Deleted/Cancelado.'),
  ('Reversão cancela o agendamento', 'um contrato aguardando aviso prévio de 60 dias', 'o Analista de Retenção aciona "Reverter Cancelamento" com motivo', 'o Contract volta a Activated, a Opportunity fecha como Retido e o agendamento some de Time-Based Automations sem nenhuma ordem gerada.'),
  ('Renegociação de prazo', 'um contrato com corte agendado para 30/12', 'o usuário altera a Data Fim do Aviso Prévio para 30/11', 'o agendamento passa a 01/12; e se tentar uma data passada, a Validation Rule bloqueia.'),
  ('Visibilidade por carteira', 'dois GRs com carteiras distintas', 'cada um abre o painel', 'vê apenas os contratos em aviso prévio das próprias contas, enquanto o perfil Retenção vê todos.'),
  ('Falha e retentativa', 'que a Integration Procedure de submissão falha', 'o scheduled path executa', 'a plataforma retenta e, esgotadas as tentativas, uma Task é criada para o BKO e o contrato aparece como "Corte com Falha".'),
  ('Reversão após submissão', 'uma ordem de desativação já submetida e ainda antes do Point of No Return', 'o BKO aciona o cancelamento in-flight', 'o OM congela a ordem e gera a suplementar; e um usuário GR não vê essa ação.')],
 massa='Cotação de cancelamento aprovada com aviso de 30 dias; manipulação da data em QA para o 31º dia; contrato com 60 dias e reversão; usuário GR de outra carteira para o critério 6.',
 fundamentacao=['Salesforce Help: Scheduled Paths (record-triggered flow); Schedule-Triggered Flow Considerations; Asset-Based Ordering; Create an Asset-Based Order in Industries CPQ; Convert an Asset to a Quote or an Order; Overview of Canceled and Amended In-Flight Orders in Order Management (Point of No Return); Order Decomposition Configuration; Troubleshooting Industries Order Management.']),

dict(COMUM, work='W-000144', codigo='B2B-15',
 titulo='Condições especiais de faturamento e intervalos de cobrança na cotação B2B',
 nota='US de negócio B2B (documento de 10/09, "Histórias novas", história 28; comentário de negócio de 14/09 na história 8: parâmetros de faturamento são preenchidos na etapa "dados de faturamento, fidelidade e tempo de contrato", depois do carrinho; W-000081 B2C-24 mantém "Mensal" somente leitura no B2C; W-000125 RN-02: nenhum cálculo financeiro no Salesforce).',
 como='Gerente de Relacionamento / Backoffice B2B',
 quero='parametrizar na cotação corporativa o intervalo de cobrança (mensal, bimestral, trimestral, semestral, anual) e a condição de vencimento, com aprovação quando fugir do padrão',
 para_que='contas governamentais e grandes grupos sejam faturados conforme o contrato sem ajuste manual no legado.',
 contexto=['Hoje o BKO configura essas condições manualmente no legado. No Industries CPQ a frequência de cobrança é propriedade da pricing variable (Charge Type Recurring + Frequency) da price list entry, ou seja, é definição de catálogo, não escolha por cotação. Criar cinco pricing variables e price list entries por frequência multiplicaria o catálogo e contraria a decisão de precificação por atributo sem produto duplicado (CAT-CPX-01).',
           'Decisão de desenho desta US: o preço da cotação continua sendo o recorrente mensal da price list; intervalo de cobrança e condição de vencimento são parâmetros contratuais do header (Quote > Order > Contract) que viajam no handoff e são aplicados pelo motor de cobrança do SAP/Customer Core.'],
 regras=[
  'RN-01 Campos no header da Quote, preenchidos pelo GR na etapa de dados de faturamento após o carrinho (junto com fidelidade e prazo): Intervalo de Cobrança (Mensal padrão, Bimestral, Trimestral, Semestral, Anual); Condição de Vencimento (Mês Corrente padrão, Mês Seguinte); Dia de Vencimento (lista permitida em Custom Metadata); Tipo de Faturamento (Padrão, Órgão Público, Conglomerado).',
  'RN-02 O preço das linhas não muda: continua o MRC mensal da price list (pricing variable recorrente mensal). O sistema apenas exibe, em campo fórmula informativo, o valor por ciclo = MRC x meses do intervalo. Nenhuma pricing variable, price list entry ou adjustment é criada por frequência.',
  'RN-03 Combinação fora do padrão (intervalo diferente de Mensal, vencimento diferente de Mês Corrente ou tipo Órgão Público/Conglomerado) bloqueia a aprovação expressa: Approval Process com critério de entrada roteia a cotação ao BKO ou Gestor Financeiro, com justificativa obrigatória e record lock durante a aprovação.',
  'RN-04 Após aprovação os campos ficam somente leitura (FLS para o GR e Validation Rule por status); alteração exige abandonar a cotação e gerar cotação filha (W-000098).',
  'RN-05 Propagação: os campos são mapeados de Quote para Order e Contract pelo Field Mapper do ABO e entram no payload de handoff do Imputar Venda (W-000101) e da decomposição (W-000088) como campos de header, com as chaves acordadas com o SAP (Billing Frequency, Payment Terms). Não são atributos de produto e não passam pelas mapping rules de produto.',
  'RN-06 De-para de valores Salesforce > SAP em Custom Metadata, mantido com Rodrigo/fiscal; valor sem de-para bloqueia o handoff com mensagem.',
  'RN-07 Pró-rata em ciclos longos é apurado pelo billing (SAP), não no Salesforce (W-000125 RN-02). O Salesforce só envia a data de início de vigência.',
  'RN-08 Elegibilidade: intervalos não mensais só para Business Account; Consumer Account mantém Mensal somente leitura (W-000081).',
  'RN-09 Multi-site: os parâmetros são do master quote e valem para todos os grupos, salvo override por grupo com a mesma alçada da RN-03.'],
 especificacao=['Campos custom em Quote, Order e Contract (mesmos API names para o mapeamento); passo do OmniScript de dados de faturamento (W-000081 estendido para B2B); campo fórmula "Valor por ciclo"; Approval Process "Condições de Faturamento Não Padrão" com record lock; Validation Rules (RN-04, RN-08); Field Mapper do ABO para Quote > Order > Asset/Contract; DataRaptor Transform do handoff (W-000101/W-000088) incluindo os campos de header; Custom Metadata de de-para SAP e de dias de vencimento.'],
 dependencias='W-000081 (etapa de dados de faturamento), W-000098 (cotação e cotação filha), W-000101 (handoff/Imputar Venda), W-000088 (decomposição e payload), W-000121 (CAT-CPX-01, Modalidade de Pagamento), Rodrigo/fiscal e SAP (chaves de Billing Frequency e Payment Terms).',
 riscos='SAP/Customer Core precisam absorver as novas chaves; contratos estaduais/federais podem exigir descrições fiscais distintas por ciclo (já tratadas por linha na W-000101).',
 estimativa='5 Story Points.',
 criterios=[
  ('Padrão', 'uma cotação B2B nova', 'o GR chega à etapa de dados de faturamento', 'Intervalo = Mensal e Condição = Mês Corrente vêm preenchidos e a cotação segue sem aprovação adicional.'),
  ('Não padrão roteia', 'uma cotação para órgão público', 'o GR seleciona Trimestral e Vencimento Mês Seguinte', 'a aprovação expressa é bloqueada, a justificativa é exigida e a cotação vai à fila do BKO/Gestor Financeiro com o registro travado.'),
  ('Preço inalterado', 'uma cotação com MRC de R$ 1.000 e intervalo Semestral', 'o carrinho é reprecificado', 'as linhas continuam com R$ 1.000 mensais e o campo informativo mostra R$ 6.000 por ciclo.'),
  ('Somente leitura após aprovação', 'uma cotação aprovada com condições não padrão', 'o GR tenta alterar o intervalo', 'o sistema bloqueia e orienta a gerar cotação filha.'),
  ('Propagação e payload', 'uma Opportunity Semestral aprovada e convertida', 'o BKO aciona Imputar Venda', 'Order e Contract carregam os mesmos valores e o payload ao SAP traz Billing Frequency e Payment Terms com as chaves do de-para.'),
  ('Sem de-para', 'um valor de intervalo sem chave SAP cadastrada', 'o handoff é acionado', 'o envio é bloqueado com mensagem indicando o valor sem de-para.'),
  ('B2C inalterado', 'uma venda B2C', 'o vendedor chega aos dados de faturamento', 'Intervalo continua "Mensal" somente leitura.')],
 massa='Cotações com "Mensal/Mês Corrente", "Trimestral/Mês Seguinte" e "Anual"; conta Consumer para o critério 7; auditoria do payload recebido pelo SAP em sandbox.',
 fundamentacao=['Salesforce Help: Pricing Definition in Industries CPQ; Create a Pricing Variable in Pricing Designer (Charge Type Recurring + Frequency); Price Assignment and the Industries CPQ Cart; Order Decomposition Configuration; Record Locking in Approval Processes.']),

dict(COMUM, work='W-000145', codigo='B2B-16',
 titulo='Cadência automática de notificações de assinatura ao cliente (proposta e contrato)',
 nota='US de negócio B2B (documento de 10/09, "Histórias novas", história 29; comentários de negócio de 14/09 nas histórias 3 e 15: régua via Marketing Cloud com templates, e-mail em D+2, D+4, D+7, D+15 e D+30 às 08h, não "após 24h"; nos demais dias o contato é do vendedor; reenvio manual e troca de e-mail permitidos). Complementa a W-000122 RN-05 (régua interna ao GR e gestor) sem duplicá-la.',
 como='Gerente de Relacionamento',
 quero='que o sistema envie ao cliente, com cópia para mim, lembretes automáticos e cadenciados de assinatura de propostas e contratos pendentes, e pare no momento em que o documento for assinado',
 para_que='o ciclo Quote-to-Order encurte sem acompanhamento manual diário.',
 contexto=['A W-000122 avisa o GR e o gestor; falta o contato com o cliente. O negócio pediu Marketing Cloud (templates e régua), que já é fundação do projeto (W-000092). O gatilho é o envio da proposta (botão "Enviar proposta comercial ao cliente", W-000098) ou do envelope de contrato/aditivo (W-000105, TEC-CLM-01). Como Quote e Contract não têm lookup de contato, e o Salesforce Data Event exige objeto com lookup para o Who (Contact), a entrada na jornada usa um registro próprio com o signatário.'],
 regras=[
  'RN-01 Escopo: propostas comerciais (Quote enviada) e contratos e aditivos (envelope enviado), B2B.',
  'RN-02 D0: o envio cria um registro "Envio para Assinatura" (objeto custom) com Tipo (Proposta/Contrato), Data de Envio, Signatário (lookup Contact, do Contact Role Signatário Legal da B2B-09), Quote ou Contract, Opportunity e Status = Pendente. Um registro por envio; novo envelope gera novo registro e reinicia a cadência.',
  'RN-03 Cadência ao cliente: D+2, D+4, D+7, D+15 e D+30, sempre às 08:00 de Brasília, e-mail ao signatário com cópia ao GR, template por tipo de documento (W-000092). Nos demais dias o contato é do vendedor.',
  'RN-04 Entrada na jornada por Salesforce Data Event no objeto Envio para Assinatura (criação, Status = Pendente), quem entra = Contact do lookup Signatário; dados da jornada: ID do envio, tipo, número da cotação/contrato, ID da Opportunity, GR e e-mail do GR, link do documento. Journey Settings: Contact Entry = "Re-entry only after exiting"; Default Email Address = "email attribute from Contacts" (a correção de e-mail feita pelo GR vale no próximo disparo).',
  'RN-05 Quebra da cadência: callback de assinatura (W-000105), aceite da proposta (Quote.Status = Aceita, W-000098), recusa ou expiração de 30 dias (W-000098/W-000122) atualizam o Status do registro para Assinado/Recusado/Expirado. Como a Data Extension do Data Event é preenchida só na entrada, a jornada verifica o Status atual do envio (objeto sincronizado pelo Marketing Cloud Connect) num Decision Split imediatamente antes de cada e-mail e sai quando Status diferente de Pendente. Nenhum envio ocorre após a saída.',
  'RN-06 Registro: cada disparo gera Task Completed na Opportunity (WhatId do Journey Data) com assunto "Lembrete de assinatura D+N", pela Task/Object activity da jornada (assíncrona, até 24 h); o Envio para Assinatura recebe "Último lembrete enviado" por Object activity (Simple Update) para auditoria imediata.',
  'RN-07 Reenvio manual e alteração do e-mail do signatário pelo GR são permitidos e não reiniciam a cadência; só um novo envelope reinicia (RN-02).',
  'RN-08 A régua interna (GR em 1, 3 e 7 dias, gestor em 15, expiração em 30) permanece na W-000122; esta US só envia ao cliente e cópia ao GR.',
  'RN-09 Limites e pré-requisitos: Marketing Cloud Connect na versão 5.496 ou superior (produção: pacote et4ae5 262.0); no máximo 80 jornadas por objeto; o objeto e o público do entry source não podem ser trocados depois de criados; Test Mode não funciona com Salesforce Entry Source nem com "No re-entry" (teste em sandbox conectada com registros reais); o objeto Envio para Assinatura entra na sincronização do Marketing Cloud Connect; atividades Sales Cloud só retentam UNABLE_TO_LOCK_ROW.',
  'RN-10 Contingência sem Marketing Cloud: schedule-triggered flow diário às 08:00 no fuso padrão da org sobre Envio para Assinatura com Status Pendente e dias desde o envio em {2, 4, 7, 15, 30}, Send Email com Organization-Wide Email Address (configurado também em Process Automation Settings > Automated Process User Email Address), Email Template Name, Recipient ID = signatário, Related Record ID = Opportunity e Log Email on Send = True. Limite de 5.000 destinatários externos por dia (GMT); cópia ao GR não conta.',
  'RN-11 LGPD: a jornada respeita a flag de opt-out do Contact enviada no evento; base legal e guarda conforme W-000083.',
  'RN-12 Lembretes nativos do DocuSign no CLM: os Vlocity CLM Custom Settings do Contract Type trazem DocuSignReminderEnabled (padrão Yes), DocuSignReminderDelay (2) e DocuSignReminderFrequency (1), cadência uniforme que conflita com a régua D+2/4/7/15/30. Para os contract types B2B: DocuSignReminderEnabled = No (a régua desta US é a única fonte de lembrete ao cliente), DocuSignExpireAfter = 30 e DocuSignExpireWarn alinhado, e ContractSignatureExpiredStatus/ContractSignatureVoidedStatus apontando para o status que a W-000122 usa ao expirar. Pré-requisito: confirmar que a assinatura da W-000105 passa pelo DocuSign do CLM; se for outro canal, a RN vale para o equivalente.'],
 especificacao=['Objeto custom Envio_para_Assinatura__c (Tipo, Data de Envio, Signatário lookup Contact, Quote, Contract, Opportunity, Status, Último Lembrete, Data de Encerramento); criação por Integration Procedure no envio da proposta (W-000098) e no envio do envelope (W-000105); record-triggered flow que atualiza Status a partir do callback e do Quote.Status; jornada no Journey Builder com entry source Salesforce Data Event, esperas até 08:00 de cada dia da régua, Decision Split por Status, atividades de e-mail, Task activity e Object activity; templates de e-mail por tipo (W-000092); contingência RN-10 (schedule-triggered flow + Send Email com org-wide address e Automated Process User Email Address configurados).'],
 dependencias='W-000092 (Marketing Cloud Connect, jornadas base, templates), W-000105 (canal e callback de assinatura), W-000098 (botão de envio e validade 30 dias), W-000122 (signatário legal e régua interna), W-000126 (TEC-CLM-01 envelope de aditivo), W-000066 (régua B2C, mesma mecânica), W-000083 (LGPD), Vlocity CLM Custom Settings por Contract Type (RN-12).',
 riscos='Callback de assinatura atrasado ou sincronização do Marketing Cloud Connect fora de hora gera lembrete indevido a quem já assinou (mitigado pelo Decision Split no momento do envio); fuso da org precisa ser America/Sao_Paulo para a régua bater com 08:00; a Task na Opportunity pode aparecer com até 24 horas de atraso.',
 estimativa='5 Story Points.',
 criterios=[
  ('D0', 'uma proposta enviada pelo botão "Enviar proposta comercial ao cliente"', 'o envio conclui', 'existe um registro Envio para Assinatura com Status Pendente, o signatário legal como contato e o Contact entrou na jornada.'),
  ('D+7 às 08:00', 'um envio com Status Pendente há exatos 7 dias', 'o relógio marca 08:00 de Brasília', 'o signatário recebe o e-mail do template de proposta com cópia ao GR, o campo "Último lembrete enviado" passa a D+7 e uma Task Completed "Lembrete de assinatura D+7" aparece na Opportunity em até 24 horas.'),
  ('Quebra por assinatura', 'um envio com lembrete D+15 previsto para amanhã', 'o callback de assinatura chega hoje à tarde', 'o Status muda para Assinado, o Contact sai da jornada e nenhum e-mail é enviado amanhã.'),
  ('Expiração', 'um envio pendente há 30 dias', 'o D+30 dispara', 'é o último e-mail e o Status passa a Expirado pela regra da W-000098.'),
  ('Reenvio manual', 'um envio pendente em D+5', 'o GR reenvia manualmente o mesmo envelope após corrigir o e-mail do signatário', 'a cadência continua contando do envio original e o próximo lembrete é D+7.'),
  ('Novo envelope', 'um envio pendente', 'um novo envelope é gerado', 'o registro anterior é encerrado e um novo D0 começa.'),
  ('Contingência', 'o Marketing Cloud indisponível e a contingência ativa', 'o schedule-triggered flow roda às 08:00', 'os envios com 2, 4, 7, 15 ou 30 dias recebem o e-mail pelo endereço organizacional, com o e-mail registrado na Opportunity e sem envio a quem já assinou.'),
  ('E-mail corrigido', 'um envio pendente cujo signatário teve o e-mail corrigido pelo GR em D+3', 'o D+4 dispara', 'o e-mail vai para o endereço corrigido do Contact.')],
 massa='Envios com Data de Envio manipulada para simular D+2, D+4 e D+30; assinatura via callback na véspera do D+15; org em fuso -03:00; verificação do log de e-mails às 08:00.',
 fundamentacao=['Salesforce Help: The Salesforce Data Event; Configure the Salesforce Data Event; Journey Settings; Sales and Service Cloud Activities; Schedule-Triggered Flows e Considerations; Send Email Action; Daily Allocations for Email Alerts; Vlocity CLM Custom Settings (DocuSign).']),
]
